        Node key = transformAsString(el.getLeft());
        Node value = transform(el.getRight());
        if (el.isGetter()) {
          key.setType(Token.GET);
          Preconditions.checkState(value.getType() == Token.FUNCTION);
          if (getFnParamNode(value).hasChildren()) {
