    private boolean isDirective(Node n) {
      if (n == null) return false;

      int nType = n.getType();
      return (nType == Token.EXPR_RESULT || nType == Token.EXPR_VOID) &&
          n.getFirstChild().getType() == Token.STRING &&
          ALLOWED_DIRECTIVES.contains(n.getFirstChild().getString());
